	if jugador == null:
		return "desconocida"
	var r: Dictionary = RecetasDB.obtener(receta_id)
	if r.is_empty():
		return "desconocida"
	if jugador.nivel < int(r.get("nivel", 1)):
		return "nivel"
	if jugador.oro < int(r.get("oro", 0)):
		return "oro"
	for m in _materiales(r):
		var md: Dictionary = m
		if jugador.inventario.contar(str(md.get("item_id", ""))) < int(md.get("cantidad", 0)):
			return "materiales"
	return "ok"


