			var mi: MeshInstance3D = n
			var sk: Skin = mi.skin if mi.skin != null else null
			extra = " malla=%s superficies=%d skin=%s" % [str(mi.mesh.get_class()), mi.mesh.get_surface_count(), "si" if sk != null else "NO"]
