import struct, json
d = open("models/clase_guerrero.glb", "rb").read()
ln, = struct.unpack_from("<I", d, 12)
j = json.loads(d[20:20+ln].decode("utf-8"))
# reconstruir la cadena de huesos en espacio glTF
padre = {c: n["children"][i] for i, n in enumerate(j["nodes"]) for c in n.get("children", [])}
pos = {}
for i, n in enumerate(j["nodes"]):
    if "mesh" in n:
        continue
    t = n.get("translation", [0, 0, 0])
    p = padre.get(i)
    base = pos.get(p, (0, 0, 0)) if p is not None else (0, 0, 0)
    pos[i] = (base[0] + t[0], base[1] + t[1], base[2] + t[2])
print("cadena reconstruida (x, y=arriba, z):")
for i, n in enumerate(j["nodes"]):
    if i in pos:
        print("  %-12s (%.2f, %.2f, %.2f)" % (n.get("name"), pos[i][0], pos[i][1], pos[i][2]))
